const d = $('Build Date Ranges').first().json;
const rowsOf = (name) => { const r = $(name).first().json; return (r && r.rows) ? r.rows : []; };
const totalsOf = (name) => rowsOf(name)[0] || {};
const num = (v) => (typeof v === 'number' && isFinite(v)) ? v : 0;

const curT = totalsOf('Totals This Week');
const prevT = totalsOf('Totals Last Week');
const curQ = rowsOf('Queries This Week');
const curP = rowsOf('Pages This Week');
const mapBy = (rows) => { const m = {}; rows.forEach((r) => { const k = (r.keys && r.keys[0] !== undefined) ? r.keys[0] : ''; m[k] = r; }); return m; };
const prevQMap = mapBy(rowsOf('Queries Last Week'));
const prevPMap = mapBy(rowsOf('Pages Last Week'));

const fmtInt = (x) => Math.round(x).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
const fmtCtr = (x) => (x * 100).toFixed(1) + '%';
const fmtPos = (x) => x.toFixed(1);

const GREEN = '#16a34a'; const RED = '#dc2626'; const GRAY = '#94a3b8';
const chip = (raw, higherBetter, fmt) => {
  const rounded = Math.round(raw * 100) / 100;
  if (Math.abs(rounded) < 0.05) return '';
  const better = higherBetter ? rounded > 0 : rounded < 0;
  const color = better ? GREEN : RED;
  const arrow = better ? '\u25B2' : '\u25BC';
  return '<div style="font-size:10px;font-weight:600;color:' + color + ';">' + arrow + fmt(Math.abs(rounded)) + '</div>';
};
const newChip = '<div style="font-size:10px;font-weight:600;color:' + GRAY + ';">new</div>';
const mTd = (valStr, chipHtml, primary) => {
  const vStyle = primary ? 'font-size:14px;font-weight:600;color:#0f172a;' : 'font-size:13px;color:#475569;';
  return '<td style="padding:10px 12px;text-align:right;border-bottom:1px solid #f2f4f8;"><div style="' + vStyle + '">' + valStr + '</div>' + (chipHtml || '') + '</td>';
};
const dataRow = (label, cur, prev) => {
  const c = { clicks: num(cur.clicks), impr: num(cur.impressions), ctr: num(cur.ctr), pos: num(cur.position) };
  let cc, ci, cr, cp;
  if (prev) {
    const p = { clicks: num(prev.clicks), impr: num(prev.impressions), ctr: num(prev.ctr), pos: num(prev.position) };
    cc = chip(c.clicks - p.clicks, true, (i) => Math.round(i).toString());
    ci = chip(c.impr - p.impr, true, (i) => Math.round(i).toString());
    cr = chip((c.ctr - p.ctr) * 100, true, (i) => i.toFixed(1));
    cp = chip(c.pos - p.pos, false, (i) => i.toFixed(1));
  } else { cc = newChip; ci = ''; cr = ''; cp = ''; }
  return '<tr>' +
    '<td style="padding:10px 12px;font-size:13px;color:#334155;border-bottom:1px solid #f2f4f8;">' + label + '</td>' +
    mTd(fmtInt(c.clicks), cc, true) + mTd(fmtInt(c.impr), ci, false) + mTd(fmtCtr(c.ctr), cr, false) + mTd(fmtPos(c.pos), cp, false) +
    '</tr>';
};
const stripUrl = (u) => ((u || '').replace(/^https?:\/\/[^/]+/, '') || '/');
const emptyRow = '<tr><td colspan="5" style="padding:14px;text-align:center;color:#94a3b8;font-size:13px;">No data for this period.</td></tr>';
const qRows = curQ.length ? curQ.map((r) => { const k = (r.keys && r.keys[0]) ? r.keys[0] : '(unknown)'; return dataRow(k, r, prevQMap[k]); }).join('') : emptyRow;
const pRows = curP.length ? curP.map((r) => { const k = (r.keys && r.keys[0]) ? r.keys[0] : ''; return dataRow(stripUrl(k), r, prevPMap[k]); }).join('') : emptyRow;

const kpiPill = (cur, prev, higherBetter, kind) => {
  const raw = kind === 'pct' ? (prev === 0 ? (cur === 0 ? 0 : 100) : ((cur - prev) / prev) * 100) : (cur - prev);
  const rounded = Math.round(raw * 10) / 10;
  const flat = Math.abs(rounded) < 0.05;
  const better = higherBetter ? raw > 0 : raw < 0;
  const color = flat ? '#64748b' : (better ? '#15803d' : '#b91c1c');
  const bg = flat ? '#f1f5f9' : (better ? '#dcfce7' : '#fee2e2');
  const arrow = flat ? '' : (better ? '\u25B2 ' : '\u25BC ');
  const mag = kind === 'pct' ? Math.abs(rounded).toFixed(1) + '%' : Math.abs(rounded).toFixed(1);
  return '<span style="font-size:11px;font-weight:600;color:' + color + ';background:' + bg + ';border-radius:999px;padding:2px 9px;">' + arrow + mag + '</span>';
};
const kpiCard = (label, valStr, pill, fromStr) =>
  '<td style="width:25%;vertical-align:top;padding:6px;">' +
  '<div style="background:#f8fafc;border:1px solid #eef1f5;border-radius:12px;padding:16px 12px;text-align:center;">' +
  '<div style="font-size:11px;color:#94a3b8;text-transform:uppercase;letter-spacing:.05em;">' + label + '</div>' +
  '<div style="font-size:26px;font-weight:700;color:#0f172a;margin:7px 0;letter-spacing:-.02em;">' + valStr + '</div>' +
  '<div>' + pill + '</div>' +
  '<div style="font-size:11px;color:#b0bac9;margin-top:7px;">from ' + fromStr + '</div>' +
  '</div></td>';
const cT = { clicks: num(curT.clicks), impr: num(curT.impressions), ctr: num(curT.ctr), pos: num(curT.position) };
const pT = { clicks: num(prevT.clicks), impr: num(prevT.impressions), ctr: num(prevT.ctr), pos: num(prevT.position) };
const cards =
  kpiCard('Clicks', fmtInt(cT.clicks), kpiPill(cT.clicks, pT.clicks, true, 'pct'), fmtInt(pT.clicks)) +
  kpiCard('Impressions', fmtInt(cT.impr), kpiPill(cT.impr, pT.impr, true, 'pct'), fmtInt(pT.impr)) +
  kpiCard('Avg CTR', fmtCtr(cT.ctr), kpiPill(cT.ctr, pT.ctr, true, 'pct'), fmtCtr(pT.ctr)) +
  kpiCard('Avg Position', fmtPos(cT.pos), kpiPill(cT.pos, pT.pos, false, 'pos'), fmtPos(pT.pos));

const th = (label, align) => '<th style="padding:10px 12px;text-align:' + align + ';font-size:10px;color:#e2e8f0;text-transform:uppercase;letter-spacing:.05em;font-weight:600;">' + label + '</th>';
const table = (firstCol, rowsHtml) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;border:1px solid #eef1f5;border-radius:10px;overflow:hidden;"><tr style="background:#0f172a;">' + th(firstCol, 'left') + th('Clicks', 'right') + th('Impr', 'right') + th('CTR', 'right') + th('Pos', 'right') + '</tr>' + rowsHtml + '</table>';

const html =
'<div style="margin:0;padding:0;background:#eef1f5;">' +
'<div style="max-width:600px;margin:0 auto;font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;background:#ffffff;border-radius:16px;overflow:hidden;">' +
  '<div style="background:#0f172a;padding:30px 32px 26px;">' +
    '<div style="font-size:20px;font-weight:600;color:#ffffff;letter-spacing:-.01em;">Search Console Weekly Report</div>' +
    '<div style="font-size:14px;color:#8ea0b8;margin-top:5px;">pocketfmmodapk.com</div>' +
  '</div>' +
  '<div style="padding:20px 32px 4px;text-align:center;font-size:13px;color:#475569;font-weight:600;">' + d.currentLabel + ' <span style="color:#94a3b8;font-weight:400;">vs</span> ' + d.previousLabel + '</div>' +
  '<div style="padding:12px 24px 22px;"><table role="presentation" width="100%" cellpadding="0" cellspacing="0"><tr>' + cards + '</tr></table></div>' +
  '<div style="padding:0 32px 6px;font-size:13px;font-weight:600;color:#0f172a;">Top queries</div>' +
  '<div style="padding:0 32px 24px;">' + table('Query', qRows) + '</div>' +
  '<div style="padding:0 32px 6px;font-size:13px;font-weight:600;color:#0f172a;">Top pages</div>' +
  '<div style="padding:0 32px 26px;">' + table('Page', pRows) + '</div>' +
  '<div style="background:#fbfcfd;padding:18px 32px;border-top:1px solid #eef1f5;font-size:11px;color:#a8b2c1;line-height:1.6;">Compares two 7 day windows ending 3 days before send, so the data is final. Green up means better than last week, red down means worse. Lower position is better. Generated ' + d.generatedAt + ' by n8n.</div>' +
'</div></div>';

const cp = pT.clicks === 0 ? 0 : Math.round(((cT.clicks - pT.clicks) / pT.clicks) * 1000) / 10;
const arrow = cp > 0 ? '\u25B2' : (cp < 0 ? '\u25BC' : '');
const subject = 'GSC Weekly - pocketfmmodapk.com - ' + fmtInt(cT.clicks) + ' clicks (' + arrow + ' ' + Math.abs(cp).toFixed(1) + '%) - ' + d.currentLabel;
return [{ json: { subject: subject, html: html } }];
